#include "stm32g4xx.h"
#include "buck_control.h"
#include "buck_config.h"
#if BUCK_OPTIMAL
#include "buck_optimal.h"

/* Thread-mode support for the ISR-side time-optimal layer. Nothing here is on
 * the pulse's critical path: the ISR triggers, solves, writes and measures;
 * the thread converts tunables, adapts and reports. FPCCR.ASPEN is cleared in
 * buck_init, so this FP adds no ISR-entry cost.
 *
 * (a) Coefficients: the setpoint (V_ref), r_off, ESR, the learned gains and b
 *     are converted into the integer solve coefficients g_buck.so, and the
 *     trigger scales V_a, dV_a, rho into the integer trigger coefficients
 *     g_buck.sa, whenever any of them changes (once at boot in buck_init;
 *     here after a Live Expressions edit or an adaptation step).
 * (b) The float trigger score of the ISR's last sample for the debug panel. */
static void buck_optimal_service(void)
{
    static uint32_t sp_c = ~0U; static int32_t gon_c = 0, goff_c = 0, ieq_c = 0; static float roff_c = -1.0f, esr_c = -1.0f;
    const uint32_t sp = g_buck_tune.setpoint_adc; const float roff = g_buck_opt_r_off_mohm, esr = g_buck_opt_esr_mohm;
    const int32_t gon = g_buck_opt_gamma_on_q16, goff = g_buck_opt_gamma_off_q16, ieq = g_buck_opt_ieq_q20;
    if (sp != sp_c || gon != gon_c || goff != goff_c || ieq != ieq_c || roff != roff_c || esr != esr_c) {
        buck_so_coef_t c;
        buck_so_coef_from_float((float)sp, roff, esr, &c);
        /* Separate stores: an ISR solve landing in between may mix old and new
         * coefficients for ONE pulse (the adaptation corrects the next). */
        g_buck.so.kv_q16 = c.kv_q16;   g_buck.so.k2_q32 = c.k2_q32;   g_buck.so.vref_q16 = c.vref_q16;
        g_buck.so.roff_q12 = c.roff_q12; g_buck.so.ndr_q8 = c.ndr_q8; g_buck.so.dq_q16 = c.dq_q16;
        g_buck.so.h_q8 = c.h_q8; g_buck.so.h2_q16 = c.h2_q16; g_buck.so.is_q20 = c.is_q20; g_buck.so.esr_cpa_q12 = c.esr_cpa_q12;
        g_buck.so.gon_q16 = gon; g_buck.so.goff_q16 = goff; g_buck.so.ieq_q20 = ieq;
        sp_c = sp; gon_c = gon; goff_c = goff; ieq_c = ieq; roff_c = roff; esr_c = esr;
    }
    static float va_c = BUCK_SA_VA_COUNTS, dva_c = BUCK_SA_DVA_COUNTS, rho_c = BUCK_SA_RHO;
    const float va = g_buck_sa_va, dva = g_buck_sa_dv, rho = g_buck_sa_rho;
    if (va != va_c || dva != dva_c || rho != rho_c) {
        buck_sa_coef_t c;
        buck_sa_coef_from_float(va, dva, rho, &c);
        /* Four separate stores: the ISR may see a mixed set for one cycle. */
        g_buck.sa.inv_va_q30 = c.inv_va_q30; g_buck.sa.inv_dva_q30 = c.inv_dva_q30;
        g_buck.sa.rho_q30 = c.rho_q30;       g_buck.sa.sq_q30 = c.sq_q30;
        va_c = va; dva_c = dva; rho_c = rho;
    }
    const float S = buck_sa_score_f((float)g_buck_opt.sa_zv, (float)g_buck_opt.sa_dv, va, dva, rho);
    g_buck_status.opt_score = (int32_t)(S * 1024.0f);              /* Q10: 1024 = boundary S=1 */
}

/* Thread-mode adaptation, once per completed transient (TPEL Sec. V): the
 * dual correction on the record the ISR closed when the linear-controller
 * transition ended (learn_req). From the record, in float:
 *   z_v,f = the first sample after the stretched period - V_ref, less the ESR
 *           term ESR (i_s - I_settled) of that sample;
 *   z_i,f = (i_s - RISE) - (I_eq - h): the measured valley after the pulse
 *           against the target valley;
 *   e_b   = I_settled - I_eq: the equilibrium error.
 * Timing gains: the Newton step on [z_i,f; z_v,f] (buck_learn_gamma; a clamped
 * pulse: Toff on z_i,f only). Equilibrium: b += mu_b e_b (buck_learn_ieq).
 * A residual beyond its SKIP bound means the pulse fired on garbage: that
 * record teaches nothing (bench 2026-09-25: zero-count samples). Then the
 * panel fields and the per-pulse log. All float/divide here is off the ISR. */
volatile buck_log_t g_buck_log[BUCK_LOG_N];
volatile uint32_t   g_buck_log_n;

static void buck_optimal_learn(void)
{
    const uint32_t req = g_buck_opt.learn_req;
    if (req == 0U) return;
    g_buck_opt.learn_req = 0U;
    const volatile buck_opt_rec_t *const r = &g_buck_opt.rec[(req - 1U) & 1U];
    const float tick = (float)BUCK_TICK_S;
    const float q20 = 1.0f / 1048576.0f, vpc = (float)(BUCK_UV_PER_COUNT * 1e-6);
    const float ieq = r->ieq_q20 * q20, i0 = r->i0_q20 * q20, zi0 = i0 - ieq;
    const float ipk = r->ipk_q16 * (1.0f / 65536.0f);
    const float h = g_buck.so.h_q8 * (1.0f / 256.0f), rise = g_buck.so.is_q20 * q20;
    const float is_f = r->is_f_q20 * q20, iset = r->iload_s_q20 * q20;
    float esr = g_buck_opt_esr_mohm * 1e-3f; if (esr < 0.0f) esr = 0.0f; else if (esr > 0.2f) esr = 0.2f;
    float roff = g_buck_opt_r_off_mohm * 1e-3f; if (roff < 0.0f) roff = 0.0f; else if (roff > 1.0f) roff = 1.0f;
    const float vref = (float)g_buck_tune.setpoint_adc * vpc;
    /* residuals */
    float zv_f = (float)r->zv_f * vpc - esr * (is_f - iset);   /* terminal voltage less the ESR term of the sample */
    float zi_f = (is_f - rise) - (ieq - h);                     /* measured valley after the pulse vs the target valley */
    float e_b  = iset - ieq;                                    /* settled load vs the equilibrium the pulse was solved for */
    uint32_t flags = 0U;
    const float zvs = (float)BUCK_OPT_ZV_SKIP_COUNTS * vpc, zvc = (float)BUCK_OPT_ZV_CLIP_COUNTS * vpc;
    if (r->ton == 0U || r->zv0 < -BUCK_OPT_ZV_SKIP_COUNTS) flags |= 3U;   /* rejected, or fired on a droop no linear-regime event makes (a dead sample) */
    if (zv_f > zvs || zv_f < -zvs || zi_f > (float)BUCK_OPT_ZI_SKIP_A || zi_f < -(float)BUCK_OPT_ZI_SKIP_A) flags |= 1U;
    if (e_b > (float)BUCK_OPT_ZI_SKIP_A || e_b < -(float)BUCK_OPT_ZI_SKIP_A) flags |= 2U;
    if (zv_f > zvc) zv_f = zvc; else if (zv_f < -zvc) zv_f = -zvc;
    if (zi_f > (float)BUCK_OPT_ZI_CLIP_A) zi_f = (float)BUCK_OPT_ZI_CLIP_A; else if (zi_f < -(float)BUCK_OPT_ZI_CLIP_A) zi_f = -(float)BUCK_OPT_ZI_CLIP_A;
    if (e_b > (float)BUCK_OPT_ZI_CLIP_A) e_b = (float)BUCK_OPT_ZI_CLIP_A; else if (e_b < -(float)BUCK_OPT_ZI_CLIP_A) e_b = -(float)BUCK_OPT_ZI_CLIP_A;
    /* timing */
    float gon = r->gon_q16 * (1.0f / 65536.0f), goff = r->goff_q16 * (1.0f / 65536.0f);
    if ((flags & 1U) == 0U) {
        const float ton_a = (float)(r->ton - BUCK_DT_FINE_TICKS) * tick, toff_a = (float)r->toff * tick;   /* applied physical times, s */
        const float m1 = ((float)BUCK_VIN_V - vref) / (float)BUCK_L_H;
        const float i2 = 0.5f * (ipk + ieq - h);                                   /* mean current of the fall */
        const float m2 = (vref + roff * i2) / (float)BUCK_L_H;
        buck_learn_gamma(&gon, &goff, ton_a, toff_a, zi0, zi_f, zv_f, m1, m2,
                         BUCK_OPT_GAMMA_MU_Q8 * (1.0f / 256.0f), r->sat,
                         (float)BUCK_OPT_GAMMA_DET_MIN_A, BUCK_OPT_GAMMA_STEP_Q16 * (1.0f / 65536.0f),
                         BUCK_OPT_GAMMA_MIN_Q16 * (1.0f / 65536.0f), BUCK_OPT_GAMMA_MAX_Q16 * (1.0f / 65536.0f));
        g_buck_opt_gamma_on_q16  = (int32_t)(gon  * 65536.0f + 0.5f);
        g_buck_opt_gamma_off_q16 = (int32_t)(goff * 65536.0f + 0.5f);
    }
    /* equilibrium */
    float b = g_buck_opt_ieq_q20 * q20;
    if ((flags & 2U) == 0U) {
        b = buck_learn_ieq(b, e_b, BUCK_OPT_IEQ_MU_Q8 * (1.0f / 256.0f), (float)BUCK_OPT_IEQ_MAX_A);
        g_buck_opt_ieq_q20 = (int32_t)(b * 1048576.0f);
    }
    /* panel */
    g_buck_status.opt_zv0 = r->zv0; g_buck_status.opt_dv0 = r->dv0;
    g_buck_status.opt_i0_ma   = (int32_t)(i0 * 1000.0f);
    g_buck_status.opt_ihat_ma = (int32_t)(ieq * 1000.0f);
    g_buck_status.opt_ipk_ma  = (int32_t)(ipk * 1000.0f);
    g_buck_status.opt_ton = r->ton; g_buck_status.opt_toff = r->toff;
    g_buck_status.opt_zvf    = r->zv_f;
    g_buck_status.opt_zif_ma = (int32_t)(zi_f * 1000.0f);
    g_buck_status.opt_zib_ma = (int32_t)(e_b * 1000.0f);
    /* per-pulse log entry (thread time only) */
    {
        volatile buck_log_t *const e = &g_buck_log[g_buck_log_n % BUCK_LOG_N];
        e->n = g_buck_log_n;
        e->zv0 = r->zv0; e->dv0 = r->dv0;
        e->ihat_ma  = (int32_t)(ieq * 1000.0f);
        e->iload_ma = (int32_t)(r->iload_q20 * (1000.0f / 1048576.0f));
        e->i0_ma    = (int32_t)(i0 * 1000.0f);
        e->ton = r->ton; e->toff = r->toff;
        e->ipk_ma   = (int32_t)(ipk * 1000.0f);
        e->term_ma  = (int32_t)(r->term_q20 * (1000.0f / 1048576.0f));
        e->sat = r->sat;
        e->zv_f = r->zv_f; e->zif_ma = (int32_t)(zi_f * 1000.0f); e->zib_ma = (int32_t)(e_b * 1000.0f);
        e->gon_q16 = g_buck_opt_gamma_on_q16; e->goff_q16 = g_buck_opt_gamma_off_q16;
        e->ieq_ma = (int32_t)(b * 1000.0f);
        e->reseed_ma = (int32_t)(r->new_iref_q16 * (1000.0f / 65536.0f));
        e->flags = flags;
        ++g_buck_log_n;
    }
}
#endif

/* Feedback-lost guard. With the loop running and the reference above 200
 * counts, a feedback sample below a quarter of the reference for longer than
 * BUCK_SENSE_GUARD_US latches BUCK_FAULT_SENSE (outputs off). An open or
 * shorted A0 reads ~0 counts, and a regulator that believes it would push the
 * full current limit into the load. Thread mode, DWT time base: no ISR cost. */
static void buck_sense_guard(void)
{
    static uint32_t t0, armed;
    const uint32_t sp = g_buck_status.setpoint, a = g_buck_status.adc_raw;
    if (g_buck_status.state == BUCK_RUNNING && sp >= 200U && a < (sp >> 2)) {
        const uint32_t now = DWT->CYCCNT;
        if (armed == 0U) { armed = 1U; t0 = now; }
        else if ((uint32_t)(now - t0) > BUCK_SENSE_GUARD_US * (BUCK_CPU_HZ / 1000000U)) buck_fatal(BUCK_FAULT_SENSE);
    } else {
        armed = 0U;
    }
}

/* One pass of the thread-mode services (the main loop body). */
void buck_thread_service(void)
{
    /* Heartbeat: if this stops counting while state==RUNNING, the ISR is
     * consuming the whole period and the thread is starved. */
    ++g_buck_status.thread_loops;
    buck_command_service();   /* STOP takes effect here (the hot ISR no longer polls it) */
    buck_sense_guard();
#if BUCK_OPTIMAL
    buck_optimal_service();
    buck_optimal_learn();
#endif
}

int main(void)
{
    buck_init();
    buck_start_sampling();
    /* Stay awake in thread mode during bring-up. Sleep-on-exit/WFI puts the
     * core to sleep between the 600 kHz interrupts, and SWD memory reads of a
     * sleeping fast-ISR target come back corrupted, so Live Expressions shows
     * flickering garbage. Spinning keeps the debug reads clean. For production
     * low-power operation, restore: SCB->SCR |= SLEEPONEXIT; for(;;) __WFI(). */
    for (;;) buck_thread_service();
}
